  'Taxonomies' => 'درجہ بندی',
  'Technical issue' => 'تکنیکی مسئلہ',
  'Technical notes for integrations with the current PlayHub API and upload workflow.' => 'موجودہ PlayHub API اور اپ لوڈ ورک فلو کے ساتھ انضمام کے لیے تکنیکی نوٹس۔',
  'Tell us more about your question or request...' => 'ہمیں اپنے سوال یا درخواست کے بارے میں مزید بتائیں...',
  'Terms of Use' => 'استعمال کی شرائط',
  'The configured' => 'تشکیل شدہ',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'ڈویلپر کا صفحہ لائیو Laravel بیک اینڈ سے منسلک ہے: روٹ انوینٹری، ڈیٹا بیس کی گنتی، اپ لوڈ کی حدیں، اور پلیٹ فارم میٹا ڈیٹا /api/developers سے لوڈ کیے جاتے ہیں۔',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'فرنٹ اینڈ ترجیحات کو اسٹور کرتا ہے جیسے کہ منتخب کردہ زبان، تھیم، پلے بیک قطار، دیکھنے کی پیشرفت، اور انٹرفیس کی حالت تاکہ تجربہ صفحہ نیویگیشن اور دوبارہ لوڈز میں یکساں رہے۔',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'پروسیسنگ جاب رینڈیشنز کو انکوڈ کرتا ہے، ضرورت پڑنے پر تھمب نیلز بناتا ہے، کیپشنز کو اسٹور کرتا ہے، اور پروسیسنگ مکمل ہونے پر ویڈیوز کو تیار نشان زد کرتا ہے۔ مستقبل کے شیڈول کردہ ویڈیوز اس وقت تک نجی رہیں گے جب تک کہ شیڈیولر انہیں جاری نہیں کرتا ہے۔',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'اپ لوڈ سسٹم ڈیٹا بیس کی حمایت یافتہ ہے، API سے زمروں اور زبانوں کو سپورٹ کرتا ہے، اپ لوڈ کردہ ویڈیوز پر کارروائی کرتا ہے، تھمب نیلز اور کیپشنز کو اسٹور کرتا ہے، اور شیڈول کردہ مواد کو اس کے ریلیز کے وقت تک نجی رکھتا ہے۔',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'یہ صفحہ بتاتا ہے کہ کس طرح PlayHub کوکیز اور براؤزر اسٹوریج کو سیشنز، سیکیورٹی، ترجیحات، پلے بیک، اور تصدیق شدہ خصوصیات کے لیے استعمال کرتا ہے۔',
  'Ticket source' => 'ٹکٹ کا ذریعہ',
  'Top content categories' => 'سب سے اوپر مواد کے زمرے',
  'Topic' => 'موضوع',
  'Transaction / invoice' => 'لین دین / رسید',
