  'Unable to submit refund request.' => 'رقم کی واپسی کی درخواست جمع کرنے سے قاصر۔',
  'Understanding admin support tickets' => 'ایڈمن سپورٹ ٹکٹ کو سمجھنا',
  'Upload and processing help' => 'اپ لوڈ اور پروسیسنگ میں مدد',
  'Upload chunks' => 'ٹکڑے اپ لوڈ کریں۔',
  'Upload issues' => 'مسائل اپ لوڈ کریں۔',
  'Upload languages' => 'زبانیں اپ لوڈ کریں۔',
  'Upload limit' => 'اپ لوڈ کی حد',
  'Upload options' => 'اپ لوڈ کے اختیارات',
  'Upload or processing' => 'اپ لوڈ یا پروسیسنگ',
  'Upload page' => 'صفحہ اپ لوڈ کریں۔',
  'Upload pipeline' => 'پائپ لائن اپ لوڈ کریں۔',
  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'لائیو PlayHub ڈیٹا کے ساتھ اپ لوڈ کریں، دیکھیں، سبسکرائب کریں، معتدل کریں اور بنائیں۔',
  'Uploaded videos' => 'اپ لوڈ کردہ ویڈیوز',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'اپ لوڈ کردہ ویڈیوز کو چلانے کے قابل رینڈیشنز میں انکوڈ کیا جاتا ہے۔ پروسیسنگ کا وقت فائل کے سائز، مدت، سرور لوڈ، اور قطار کی حیثیت پر منحصر ہے۔ اپ لوڈ صفحہ اور تخلیق کار اسٹوڈیو ویڈیو ریکارڈ سے حقیقی پروسیسنگ کی حیثیت دکھاتے ہیں۔',
  'Uploads, scheduling, and processing are available.' => 'اپ لوڈز، شیڈولنگ، اور پروسیسنگ دستیاب ہیں۔',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'تخلیق کار کے ورک فلو کے لیے /api/ویڈیوز، چینل اینڈ پوائنٹس، اور تصدیق شدہ راستے استعمال کریں۔',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'ویڈیوز اور تبصروں کے لیے بلٹ ان رپورٹ ایکشنز کا استعمال کریں تاکہ منتظمین کو مواد کا صحیح حوالہ مل سکے۔ ایڈمن ڈیش بورڈ پیجز صارفین، مواد، رپورٹس، منیٹائزیشن، اینالیٹکس، سپورٹ، رولز اور سسٹم سیٹنگز کے لیے لائیو ڈیٹا بیس کا ڈیٹا استعمال کرتے ہیں۔',
  'Use Contact Us' => 'ہم سے رابطہ کریں استعمال کریں۔',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'عام API درخواستوں کے لیے JSON اور فائل اپ لوڈز کے لیے FormData استعمال کریں۔ توثیق کو نظرانداز نہ کریں: زمرہ جات اور زبانیں ڈیٹابیس IDs ہیں، مرئیت عوامی، غیر فہرست شدہ، یا نجی تک محدود ہے، اور کیپشنز SRT، VTT، یا TXT فائلوں کو قبول کرتے ہیں۔',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'اپنے پروفائل، سیکیورٹی، پاس ورڈ، دو عنصر کی ترسیل، آلات، ترجیحات، اور اطلاع کے اختیارات کو اپ ڈیٹ کرنے کے لیے ترتیبات کا استعمال کریں۔ اگر آپ اپنے اکاؤنٹ تک رسائی حاصل نہیں کر سکتے تو لاگ ان فلو استعمال کریں اور سائٹ کے منتظم کو اکاؤنٹ ای میل فراہم کریں۔',
  'Use the contact form' => 'رابطہ فارم استعمال کریں۔',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'ویڈیوز، تبصروں اور کمیونٹی پوسٹس پر رپورٹ کی کارروائیوں کا استعمال کریں تاکہ منتظمین کو مواد کا صحیح حوالہ مل سکے۔',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'جب مواد پلیٹ فارم کے قوانین کی خلاف ورزی کر سکتا ہے تو ویڈیوز، تبصروں اور کمیونٹی پوسٹس پر رپورٹ کی کارروائیوں کا استعمال کریں۔ یہ رپورٹس حقیقی مواد کے ریکارڈ سے منسلک ہیں اور ایک عام پیغام سے بہتر ہیں کیونکہ منتظمین درست آئٹم کا جائزہ لے سکتے ہیں۔',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'اکاؤنٹ کی مدد، مواد کی رپورٹس، تکنیکی مسائل، اور منتظم کی درخواستوں کے لیے صحیح PlayHub چینل استعمال کریں۔',
  'Video categories' => 'ویڈیو کے زمرے',
  'Video for everyone. Built for creators and viewers.' => 'ویڈیو سب کے لیے۔ حقیقی پلیٹ فارم ڈیٹا سے بنایا گیا ہے۔',
  'Video upload, scheduling, thumbnails, and processing issues.' => 'ویڈیو اپ لوڈ، شیڈولنگ، تھمب نیلز، اور پروسیسنگ کے مسائل۔',
  'Videos, thumbnails, captions, processing.' => 'ویڈیوز، تھمب نیلز، کیپشنز، پروسیسنگ۔',
  'Viewers can browse categories, search videos, watch content, subscribe to channels, save videos to watch later, comment, receive notifications, and manage language and accessibility preferences.' => 'ناظرین زمرے براؤز کر سکتے ہیں، ویڈیوز تلاش کر سکتے ہیں، مواد دیکھ سکتے ہیں، چینلز کو سبسکرائب کر سکتے ہیں، بعد میں دیکھنے کے لیے ویڈیوز محفوظ کر سکتے ہیں، تبصرہ کر سکتے ہیں، اطلاعات وصول کر سکتے ہیں، اور زبان اور رسائی کی ترجیحات کا نظم کر سکتے ہیں۔',
  'Viewing and community help' => 'دیکھنا اور کمیونٹی کی مدد',
  'Waiting for backend endpoint inventory.' => 'بیک اینڈ اینڈ پوائنٹ انوینٹری کا انتظار ہے۔',
  'We’re here to help.' => 'ہم یہاں مدد کرنے کے لیے ہیں۔',
  'What is PlayHub?' => 'PlayHub کیا ہے؟',
  'What PlayHub does' => 'PlayHub کیا کرتا ہے۔',
  'Where do contact messages go?' => 'رابطے کے پیغامات کہاں جاتے ہیں؟',
  'Why is my video still processing?' => 'میری ویڈیو پر ابھی تک کارروائی کیوں ہو رہی ہے؟',
  'Yes. Use the native schedule date and time field on the upload page. The backend stores scheduled_at, processes the video, keeps it private while the date is in the future, and releases it when the Laravel scheduler runs after the scheduled time.' => 'جی ہاں اپ لوڈ صفحہ پر مقامی شیڈول کی تاریخ اور وقت کی فیلڈ کا استعمال کریں۔ بیک اینڈ شیڈیولڈ_اٹ اسٹور کرتا ہے، ویڈیو پر کارروائی کرتا ہے، تاریخ مستقبل میں ہونے کے دوران اسے نجی رکھتا ہے، اور جب Laravel شیڈولر مقررہ وقت کے بعد چلتا ہے تو اسے جاری کرتا ہے۔',
  'Yes. Use the native schedule field on Upload. The backend stores scheduled_at and releases the video after processing when the schedule time is reached.' => 'جی ہاں اپ لوڈ پر مقامی شیڈول فیلڈ کا استعمال کریں۔ بیک اینڈ شیڈیولڈ_اٹ کو اسٹور کرتا ہے اور جب شیڈول کا وقت پورا ہوجاتا ہے تو پروسیسنگ کے بعد ویڈیو جاری کرتا ہے۔',
  'You are browsing as a guest. Sign in to access account-specific tools.' => 'آپ بطور مہمان براؤز کر رہے ہیں۔ اکاؤنٹ کے مخصوص ٹولز تک رسائی کے لیے سائن ان کریں۔',
  'You are responsible for your account credentials, profile activity, uploaded content, comments, messages, and any creator or admin actions performed from your account. Use strong passwords and keep two-factor delivery methods current.' => 'آپ اپنے اکاؤنٹ کی اسناد، پروفائل کی سرگرمی، اپ لوڈ کردہ مواد، تبصرے، پیغامات، اور آپ کے اکاؤنٹ سے انجام پانے والے کسی بھی تخلیق کار یا منتظم کے اعمال کے ذمہ دار ہیں۔ مضبوط پاس ورڈ استعمال کریں اور دو فیکٹر ڈیلیوری طریقوں کو موجودہ رکھیں۔',
  'You can clear browser cookies and local storage in your browser settings. Clearing essential storage may sign you out, reset language/theme preferences, remove local playback state, and require you to log in again.' => 'آپ اپنے براؤزر کی ترتیبات میں براؤزر کوکیز اور مقامی اسٹوریج کو صاف کر سکتے ہیں۔ ضروری اسٹوریج کو صاف کرنے سے آپ سائن آؤٹ ہو سکتے ہیں، زبان/تھیم کی ترجیحات کو دوبارہ ترتیب دے سکتے ہیں، مقامی پلے بیک حالت کو ہٹا سکتے ہیں، اور آپ کو دوبارہ لاگ ان کرنے کی ضرورت پڑ سکتی ہے۔',
  'You receive a response by email.' => 'آپ کو ای میل کے ذریعے جواب موصول ہوتا ہے۔',
  'You’re in control' => 'آپ کنٹرول میں ہیں۔',
  'Your choices' => 'آپ کے انتخاب',
  'Your message is saved directly in the website backend and appears in the admin dashboard under Support.' => 'آپ کا پیغام براہ راست ویب سائٹ کے بیک اینڈ میں محفوظ ہوتا ہے اور سپورٹ کے تحت ایڈمن ڈیش بورڈ میں ظاہر ہوتا ہے۔',
  'Your support' => 'آپ کی حمایت',
