  'Clear' => 'صاف',
  'Tip' => 'ٹپ',
  'Use playlists to organize your content and make it easier for your audience to discover more videos.' => 'اپنے مواد کو منظم کرنے کے لیے پلے لسٹس کا استعمال کریں اور اپنے ناظرین کے لیے مزید ویڈیوز دریافت کرنا آسان بنائیں۔',
